CREATE TABLE IF NOT EXISTS groups (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, archived boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS subjects (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, archived boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS users (id bigint PRIMARY KEY, name text NOT NULL DEFAULT '', group_id bigint REFERENCES groups, teacher boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments (subject_id bigint REFERENCES subjects, group_id bigint REFERENCES groups, teacher_id bigint REFERENCES users, PRIMARY KEY(subject_id,group_id,teacher_id));
CREATE TABLE IF NOT EXISTS labs (id bigserial PRIMARY KEY, subject_id bigint NOT NULL REFERENCES subjects, group_id bigint NOT NULL REFERENCES groups, number integer NOT NULL CHECK(number>0), name text NOT NULL, archived boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS lab_number ON labs(subject_id,group_id,number) WHERE NOT archived;
CREATE TABLE IF NOT EXISTS events (id bigserial PRIMARY KEY, name text NOT NULL, subject_id bigint NOT NULL REFERENCES subjects, teacher_id bigint NOT NULL REFERENCES users, starts_at timestamptz NOT NULL, room text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', duration integer NOT NULL DEFAULT 0 CHECK(duration>=0), state text NOT NULL DEFAULT 'planned' CHECK(state IN ('planned','live','completed','cancelled')), registration_open boolean NOT NULL DEFAULT false, strategy text NOT NULL CHECK(strategy IN ('fifo','asc','desc','random')), shuffled boolean NOT NULL DEFAULT false, first_called boolean NOT NULL DEFAULT false, manual_order boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS event_groups (event_id bigint REFERENCES events, group_id bigint REFERENCES groups, PRIMARY KEY(event_id,group_id));
CREATE TABLE IF NOT EXISTS entries (id bigserial PRIMARY KEY, event_id bigint NOT NULL REFERENCES events, user_id bigint NOT NULL REFERENCES users, state text NOT NULL DEFAULT 'waiting' CHECK(state IN ('waiting','called','completed','left','removed','closed')), position bigint NOT NULL, score integer NOT NULL, skipped boolean NOT NULL DEFAULT false, joined_at timestamptz NOT NULL DEFAULT clock_timestamp(), called_at timestamptz, ended_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_entry ON entries(event_id,user_id) WHERE state IN ('waiting','called');
CREATE UNIQUE INDEX IF NOT EXISTS one_called_entry ON entries(event_id) WHERE state='called';
CREATE TABLE IF NOT EXISTS grades (student_id bigint REFERENCES users, lab_id bigint REFERENCES labs, value integer CHECK(value BETWEEN 2 AND 5), version integer NOT NULL DEFAULT 1, author_id bigint REFERENCES users, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(student_id,lab_id));
CREATE TABLE IF NOT EXISTS audit (id bigserial PRIMARY KEY, actor_id bigint NOT NULL, action text NOT NULL, payload jsonb NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id bigserial PRIMARY KEY, recipient bigint NOT NULL, entry_id bigint REFERENCES entries, event_id bigint REFERENCES events, kind text NOT NULL, message text NOT NULL, attempts integer NOT NULL DEFAULT 0, next_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE(entry_id,kind));
CREATE TABLE IF NOT EXISTS requests (user_id bigint NOT NULL, key text NOT NULL, body_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,key));
CREATE INDEX IF NOT EXISTS entries_event ON entries(event_id,position);
CREATE INDEX IF NOT EXISTS notifications_pending ON notifications(next_at) WHERE delivered_at IS NULL;
